leted, row_number() OVER (PARTITION BY user_key, blocked_key ORDER BY updated_at DESC, deleted DESC) AS rn FROM user_blacklist) WHERE rn = 1 AND deleted = 0 AND blocked_key = 'rd42-u0980001') AND d.author_key NOT IN (SELECT username FROM (SELECT username, deleted, row_number() OVER (PARTITION BY username ORDER BY updated_at DESC, deleted DESC) AS rn FROM banned_users) WHERE rn = 1 AND deleted = 0)) SELECT p.doc_id AS doc_id, p.author_key AS author_key, p.posted_by AS posted_by, p.group_id AS group_id, p.body AS body, p.tags AS tags, p.created_at AS created_at, p.ref_value AS ref_value, p.ad_mode AS ad_mode, p.ad_target AS ad_target, coalesce(eng.like_count, 0) AS likes, coalesce(eng.dislike_count, 0) AS dislikes, coalesce(rp.repost_count, 0) AS reposts, coalesce(cmt.comment_count, 0) AS comments, (0) AS score, pr.body AS profile_body FROM posts AS p LEFT JOIN (SELECT ref_value, countIf(JSONExtractString(body, 'type') = 'like') AS like_count, countIf(JSONExtractString(body, 'type') = 'dislike') AS dislike_count FROM reactions WHERE ref_value <> '' GROUP BY ref_value) AS eng ON eng.ref_value = p.doc_id LEFT JOIN (SELECT JSONExtractString(body, 'repost_of') AS repost_of, count() AS repost_count FROM posts WHERE JSONExtractString(body, 'repost_of') <> '' GROUP BY repost_of) AS rp ON rp.repost_of = p.doc_id LEFT JOIN (SELECT JSONExtractString(body, 'post_id') AS post_id, count() AS comment_count FROM comments WHERE JSONExtractString(body, 'post_id') <> '' GROUP BY post_id) AS cmt ON cmt.post_id = p.doc_id LEFT JOIN (SELECT author_key, body FROM profile QUALIFY row_number() OVER (PARTITION BY author_key ORDER BY updated_at DESC) = 1) AS pr ON pr.author_key = p.author_key WHERE NOT has(p.tags, 'ad') AND NOT has(p.tags, 'product') ORDER BY toUnixTimestamp64Milli(p.created_at) DESC LIMIT 21
